// === Tab: Sketch ===
// By Roni Kaufman
// inspired by Vera Molnar's "Quatre éléments distribués au hasard" (1959)

let composition = [];
// 0: -
// 1: /
// 2: |
// 3: \
let n = 24 // number of elements per lign and column
let size = 512/24; // size of each element
let margin = 44;
let colors;

let randInt = (x) => (floor(random(x)));

function setup() {
  createCanvas(600, 600);
  //// noLoop() removed for animation
	colorMode(HSB, 1);
	colors = [color(0.15, 0.9, 1), color(0)];
	stroke(colors[1]);
	strokeWeight(5);
	frameRate(1);

	for (let i = 0; i < n; i++) {
		composition.push([]);
		for (let j = 0; j < n; j++) {
			composition[i].push(randInt(4));
		}
	}
}

function draw() {
	background(colors[0]);
  drawComposition();
	changeOneElement();
}

function drawComposition() {
	push();
	translate(margin, margin);
	for (let i = 0; i < n; i++) {
		for (let j = 0; j < n; j++) {
			let x = i * size;
			let y = j * size;
			switch (composition[i][j]) {
				case 0:
					strokeCap(SQUARE);
					line(x, y + size/2, x + size, y + size/2);
					break;
				case 1:
					strokeCap(PROJECT);
					line(x, y + size, x + size, y);
					break;
				case 2:
					strokeCap(SQUARE);
					line(x + size/2, y, x + size/2, y + size);
					break;
				case 3:
					strokeCap(PROJECT);
					line(x, y, x + size, y + size);
			}
		}
	}
	pop();
}

function changeOneElement() {
	let i = randInt(n);
	let j = randInt(n);
	let oldEl = composition[i][j];
	let newEl;
	do {
		newEl = randInt(4);
	} while (newEl === oldEl);
	composition[i][j] = newEl;
}
